{
  "_comment": "The gates a local pre-push runs that a CI checkout legitimately cannot or need not re-run. Every OTHER pre-push gate must appear as a step in .github/workflows/gates.yml, or check-ci-mirror.sh (SPEC INV-210) reds. Each carve-out states why it stays out of CI, so the line is settled and not re-walked. A carve-out naming a letter that is no local gate is itself drift and reds.",
  "ci_excluded": {
    "c": "Folded into the test suite: tests/test_traceability.py asserts anchor ownership and runs inside the pytest step (gate b), so this check is already covered in CI.",
    "k": "The compaction freeze reads a gitignored local baseline (.spec-freeze/) that a fresh CI checkout does not carry.",
    "m": "config-health compares the installed personal hooks against their source; a CI checkout installs no such hooks by design and the check skips itself by name.",
    "v": "The judge-listed gate reads the personal-layer ~/.claude/settings.json, absent on a CI checkout; it stands down by name there, exactly as config-health (m) skips."
  }
}
=== hook-red-proofs.json ===
{
 "_comment": "The known-red proof for every session hook (Stop / UserPromptSubmit), the hook-side sibling of guardrails/gate-red-proofs.json (which covers pre-push gates only and reaches zero hooks). A hook nobody can make fire is a check that watches nothing, the same disease gate-red-proofs.json exists to catch on the push side. guardrails/check-hooks-can-fire.py reads this file: each `proofs` entry names a fixture directory under guardrails/hook-red-fixtures/ that MUST make the hook print a live decision when the hook is run against it for real (no test mocks the hook's own logic — the runner executes the actual script). A `cannot_red` entry names a hook whose own stdout can never carry a verdict by design, with the one-sentence reason, the same shape gate-red-proofs.json's cannot_red carries for a gate that can never fail. A hook classified nowhere, or found under hooks/ or ~/.claude/hooks/ but absent from both maps, is the finding.",
 "proofs": {
  "scissors-scan.py": {
   "fixture": "hook-red-fixtures/scissors-scan",
   "detect": "json-block",
   "note": "fires on the English contrast frame 'X, not Y' in the assistant reply"
  },
  "hedge-scan.py": {
   "fixture": "hook-red-fixtures/hedge-scan",
   "detect": "json-block",
   "note": "fires on the offering-hedge frame 'just say the word'"
  },
  "affirmation-scan.py": {
   "fixture": "hook-red-fixtures/affirmation-scan",
   "detect": "json-block",
   "note": "fires on validating the user ('you're absolutely right', 'great catch')"
  },
  "lean-orchestrator-scan.py": {
   "fixture": "hook-red-fixtures/lean-orchestrator-scan",
   "detect": "json-block",
   "note": "fires on cumulative inline Read/dump content over the threshold with zero Agent/Task dispatches; OFF by default (opt-in net, guardrails/judge-hooks.json library entry) but still owed a red proof of its own logic"
  },
  "register-judge-report.sh": {
   "fixture": "hook-red-fixtures/register-judge-report",
   "detect": "nonempty-contains",
   "contains": "REGISTER JUDGE",
   "note": "reads a pre-seeded verdict file under $HOME/.claude/hooks/.judge/<session>.json and prints its reason; the runner isolates $HOME to a temp dir per run so no real verdict state is touched"
  },
  "code-anchor-scan.py": {
   "fixture": "hook-red-fixtures/code-anchor-scan",
   "detect": "json-block",
   "note": "fires on a queue row number left standing in prose with no plain-word naming of the wish (the 2026-07-27 live failure, verbatim)"
  },
  "clock-hook.sh": {
   "fixture": "hook-red-fixtures/clock-hook",
   "detect": "nonempty-contains",
   "contains": "Wall clock at this prompt",
   "note": "prints the wall clock line unconditionally on every UserPromptSubmit; a stub payload is enough to fire it"
  },
  "chat-law-hook.sh": {
   "fixture": "hook-red-fixtures/chat-law-hook",
   "detect": "nonempty-contains",
   "contains": "Session laws (live-spec)",
   "note": "prints the chat-law reminder line unconditionally on every UserPromptSubmit; a stub payload is enough to fire it. The caught phrase was 'Answer first (live-spec)' until 2026-08-17, when the owner had the hook shrunk from nine lines retelling the seven laws in full to one line naming them and pointing at their texts; 'Session laws (live-spec)' opens that line, so this proof catches the same unconditional fire"
  },
  "worker-restore-guard.py": {
   "fixture": "hook-red-fixtures/worker-restore-guard",
   "detect": "json-deny",
   "note": "fires on `git stash push -q tests/test_spec_parts.py`, the exact command a worker whose brief read 'HOSTILE reviewer ... Do NOT modify any file' ran at 2026-08-18T07:44:14Z (ROADMAP row 479); the first PreToolUse hook this pack wires since the tool-boundary chat arm's 2026-08-17 retirement, and unlike that arm it needs no seat-versus-worker distinction to be safe (see the hook's own docstring)"

